from taf.rfrl.csv4all.resources.utilities.exceptions import MainExceptionClass


class CopySwToNetactError(Exception):
    """ Error when copying sw to netact fail """
    def __init__(self, output, error):
        super().__init__(f"\nOutput {output}"
                         f"\nRaised exception: {error}")


class ImportSwToNetactError(MainExceptionClass):
    """ Error when importing sw to netact fail """
    pass


class VerifyCellsNetactError(Exception):
    """ Error when checking cells state from netact failed """
    pass


class SoftwareStatusError(Exception):
    """ Error when software status is not correct """
    pass


class NotValidNetact(Exception):
    """ Error when provided Netact is not supported"""
    pass


class FallbackFaultNotExists(Exception):
    """ Error when fallback fault not appear after fallback"""
    pass


class PreconditionBeforeFallack(Exception):
    """ Raise when preparing for fallback fail """
    pass


class ExecutingResetLoopFail(Exception):
    """ Raise when executing reset loop fail """
    pass

class NodeVerificationFail(Exception):
    """ Raise when verification node after fallback fail """
    pass
